use super::Percentage;

#[derive(Clone, Debug, Default)]
pub struct ProgressBar {
    progress: usize,
    total: usize,
    width: usize,
}

impl ProgressBar {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn set_progress(&mut self, progress: usize) {
        self.progress = progress;
    }

    pub fn set_total(&mut self, total: usize) {
        self.total = total;
    }

    pub fn set_width(&mut self, width: usize) {
        self.width = width;
    }

    pub fn str(&self) -> String {
        let pos = self.position();
        let mut bar = String::with_capacity(self.width + 10);
        bar.push('[');

        for index in 0..self.width {
            if index < pos {
                bar.push('=');
            } else if index == pos && pos < self.width {
                bar.push('>');
            } else {
                bar.push(' ');
            }
        }

        bar.push(']');
        bar.push(' ');
        bar.push_str(&Percentage::new(self.ratio()).str());
        bar
    }

    fn position(&self) -> usize {
        if self.total == 0 {
            return 0;
        }

        self.progress
            .saturating_mul(self.width)
            .checked_div(self.total)
            .unwrap_or(0)
            .min(self.width)
    }

    fn ratio(&self) -> f32 {
        if self.total == 0 {
            return 0.0;
        }

        self.progress as f32 / self.total as f32
    }
}

